{
  "originalFormula": "V_{bi} = |\phi_{pn}| + |\phi_{rp}|",
  "genericFormula": "V_{bi} = |\phi_{pn}| + |\phi_{rp}|",
  "description": "Esta fórmula representa a tensão de polarização interna de uma junção p-n, que é a diferença de potencial elétrico que se forma na junção devido à difusão de portadores de carga. Essa tensão é crucial para entender o funcionamento de dispositivos semicondutores, como diodos e transistores.",
  "concepts": [
    "Tensão de polarização interna",
    "Junção p-n",
    "Difusão de portadores de carga",
    "Dispositivos semicondutores"
  ],
  "symbols": [
    {
      "symbol": "V_{bi}",
      "description": "Representa a tensão de polarização interna da junção p-n."
    },
    {
      "symbol": "|\phi_{pn}|",
      "description": "Representa o potencial elétrico associado à junção p-n, que resulta da diferença de concentração de portadores de carga nas regiões p e n."
    },
    {
      "symbol": "|\phi_{rp}|",
      "description": "Representa o potencial elétrico associado à região de depleção na junção p-n, que é a região onde não há portadores de carga livres devido à recombinação."
    }
  ]
}
